import{_ as e,o as s,c as a,a2 as o}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"Configuration Reference","description":"","frontmatter":{},"headers":[],"relativePath":"liteshield-xdp/configuration/reference.md","filePath":"liteshield-xdp/configuration/reference.md","lastUpdated":null}'),d={name:"liteshield-xdp/configuration/reference.md"};function r(i,t,n,l,h,c){return s(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="configuration-reference" tabindex="-1">Configuration Reference <a class="header-anchor" href="#configuration-reference" aria-label="Permalink to &quot;Configuration Reference&quot;">​</a></h1><blockquote><p><strong>The definitive reference for every LiteShield XDP configuration value.</strong> Generated from the actual defaults in <code>userspace/internal/config/defaults.go</code> and the example at <code>configs/liteshield.example.yaml</code>.</p></blockquote><nav class="table-of-contents"><ul><li><a href="#overview">Overview</a></li><li><a href="#_1-interface-interface">1. Interface (interface)</a><ul><li><a href="#interface">interface</a></li></ul></li><li><a href="#_2-xdp-mode-xdp-mode">2. XDP Mode (xdp_mode)</a><ul><li><a href="#xdp-mode">xdp_mode</a></li></ul></li><li><a href="#_3-thresholds-thresholds">3. Thresholds (thresholds)</a><ul><li><a href="#thresholds-pps">thresholds.pps</a></li><li><a href="#thresholds-syn">thresholds.syn</a></li><li><a href="#thresholds-udp">thresholds.udp</a></li><li><a href="#thresholds-icmp">thresholds.icmp</a></li><li><a href="#thresholds-new-src">thresholds.new_src</a></li><li><a href="#thresholds-flow-pps">thresholds.flow_pps</a></li><li><a href="#thresholds-flow-bps">thresholds.flow_bps</a></li></ul></li><li><a href="#_4-auto-ban-ban-duration-sec">4. Auto-Ban (ban_duration_sec)</a><ul><li><a href="#ban-duration-sec">ban_duration_sec</a></li></ul></li><li><a href="#_5-discord-discord">5. Discord (discord)</a><ul><li><a href="#discord-webhook-url">discord.webhook_url</a></li><li><a href="#discord-events">discord.events</a></li><li><a href="#discord-min-interval-sec">discord.min_interval_sec</a></li></ul></li><li><a href="#_6-presets-multipliers">6. Presets &amp; Multipliers</a><ul><li><a href="#base-rates-balanced-1-0×">Base rates (Balanced = 1.0×)</a></li><li><a href="#traffic-profile-multipliers">Traffic profile multipliers</a></li><li><a href="#effective-values-example-personal-×-strict">Effective values example (Personal × Strict)</a></li></ul></li><li><a href="#_7-validation-rules">7. Validation Rules</a></li></ul></nav><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>LiteShield is configured through a single YAML file at <code>/etc/liteshield/liteshield.yaml</code>. The loader merges your file with built-in defaults (Hosting/Balanced) — any key you omit retains its default value. Validation runs at load time and rejects bad values before the XDP program attaches.</p><p><strong>Configuration precedence (highest to lowest):</strong></p><ol><li>YAML configuration file</li><li>Built-in Go defaults (<code>Default()</code> → Hosting preset, Balanced profile)</li></ol><div class="tip custom-block"><p class="custom-block-title">Edit with hot-reload</p><p>Use <code>sudo liteshield config</code> instead of editing the file by hand. It opens the config in your <code>$EDITOR</code>, validates it, and applies the new thresholds to the running instance — no detach, no protection gap.</p></div><p><strong>Full annotated example:</strong></p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># LiteShield XDP — example configuration</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">interface</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">eth0</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># XDP attach mode: auto | native | generic</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">xdp_mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">auto</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">thresholds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  pps</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">200000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # max total packets/sec per source IP</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  syn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # max TCP SYN/sec per source IP</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  udp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # max UDP packets/sec per source IP</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  icmp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # max ICMP packets/sec per source IP</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  new_src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # max new source IPs/sec (global)</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  flow_pps</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # max packets/sec per flow</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  flow_bps</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20000000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # max bytes/sec per flow (~20 MB/s)</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ban_duration_sec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">discord</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  webhook_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  events</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">rule_trigger</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ip_banned</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">new_source</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  min_interval_sec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span></span></code></pre></div><hr><h2 id="_1-interface-interface" tabindex="-1">1. Interface (<code>interface</code>) <a class="header-anchor" href="#_1-interface-interface" aria-label="Permalink to &quot;1. Interface (`interface`)&quot;">​</a></h2><h3 id="interface" tabindex="-1"><code>interface</code> <a class="header-anchor" href="#interface" aria-label="Permalink to &quot;`interface`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>YAML path</strong></td><td><code>interface</code></td></tr><tr><td><strong>Type</strong></td><td><code>string</code></td></tr><tr><td><strong>Default</strong></td><td><code>&quot;eth0&quot;</code></td></tr><tr><td><strong>Required</strong></td><td>Yes (must not be empty)</td></tr></tbody></table><p>The network interface the XDP program attaches to. All enforcement happens on inbound packets arriving at this interface.</p><p><strong>When to change it:</strong></p><ul><li>Set it to your public-facing NIC (the one in your default route). The installer auto-detects this; a manual install defaults to <code>eth0</code>, which may not exist on predictable-name systems (<code>ens18</code>, <code>enp1s0</code>, …).</li><li>Changing the interface requires a reload: <code>sudo liteshield unload &amp;&amp; sudo liteshield load</code> (or restart the systemd service). Hot-reload only applies thresholds, not the attach point.</li></ul><div class="warning custom-block"><p class="custom-block-title">Common mistake</p><p>Attaching to <code>docker0</code>, <code>lo</code>, or a bridge instead of the physical NIC. LiteShield only sees packets arriving at the attached interface — traffic on other interfaces is unprotected.</p></div><hr><h2 id="_2-xdp-mode-xdp-mode" tabindex="-1">2. XDP Mode (<code>xdp_mode</code>) <a class="header-anchor" href="#_2-xdp-mode-xdp-mode" aria-label="Permalink to &quot;2. XDP Mode (`xdp_mode`)&quot;">​</a></h2><h3 id="xdp-mode" tabindex="-1"><code>xdp_mode</code> <a class="header-anchor" href="#xdp-mode" aria-label="Permalink to &quot;`xdp_mode`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>YAML path</strong></td><td><code>xdp_mode</code></td></tr><tr><td><strong>Type</strong></td><td><code>string</code></td></tr><tr><td><strong>Default</strong></td><td><code>&quot;auto&quot;</code></td></tr><tr><td><strong>Valid values</strong></td><td><code>&quot;auto&quot;</code>, <code>&quot;native&quot;</code>, <code>&quot;generic&quot;</code> (also empty = auto)</td></tr></tbody></table><p>How the XDP program attaches to the interface.</p><table tabindex="0"><thead><tr><th>Mode</th><th>Behavior</th><th>Performance</th></tr></thead><tbody><tr><td><code>auto</code></td><td>Try native (driver) first, fall back to generic</td><td>Best available</td></tr><tr><td><code>native</code></td><td>Driver mode only — fails if the NIC driver lacks XDP support</td><td>Best</td></tr><tr><td><code>generic</code></td><td>SKB mode — works on every interface</td><td>Slower, still pre-conntrack</td></tr></tbody></table><p><strong>When to change it:</strong></p><ul><li>Leave at <code>auto</code> in almost all cases.</li><li>Set <code>native</code> if you want a hard failure (instead of a silent fallback) when the driver doesn&#39;t support XDP — useful in performance-critical deployments where generic mode would mask a problem.</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Native-capable drivers include <code>ixgbe</code>, <code>i40e</code>, <code>mlx4/mlx5</code>, <code>bnxt</code>, <code>virtio_net</code>, and most modern NICs. The active mode is shown in the TUI header and in <code>ip link show dev &lt;iface&gt;</code>.</p></div><hr><h2 id="_3-thresholds-thresholds" tabindex="-1">3. Thresholds (<code>thresholds</code>) <a class="header-anchor" href="#_3-thresholds-thresholds" aria-label="Permalink to &quot;3. Thresholds (`thresholds`)&quot;">​</a></h2><p>Rate limits enforced <strong>per source IP, per second</strong>, on a 1-second sliding window — except <code>new_src</code>, which is a <strong>global</strong> limit. Exceeding a threshold drops the packet and (if <code>ban_duration_sec &gt; 0</code>) starts an auto-ban.</p><h3 id="thresholds-pps" tabindex="-1"><code>thresholds.pps</code> <a class="header-anchor" href="#thresholds-pps" aria-label="Permalink to &quot;`thresholds.pps`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>YAML path</strong></td><td><code>thresholds.pps</code></td></tr><tr><td><strong>Type</strong></td><td><code>uint64</code></td></tr><tr><td><strong>Default</strong></td><td><code>200000</code> (Hosting/Balanced)</td></tr><tr><td><strong>Required</strong></td><td>Yes (must be &gt; 0)</td></tr></tbody></table><p>Maximum total packets per second from a single source IP, across all protocols. This is the catch-all ceiling that bounds any single talker.</p><p><strong>When to change it:</strong></p><ul><li><strong>Decrease</strong> on small pipes (home lines, 100 Mbps VPS) where a single source should never legitimately exceed a few thousand PPS.</li><li><strong>Increase</strong> if you serve high-PPS legitimate traffic from concentrated sources (load balancer health checks, database replication, game server queries behind NAT).</li></ul><div class="warning custom-block"><p class="custom-block-title">Common mistake</p><p>Setting <code>pps</code> below your NAT gateway&#39;s legitimate rate. Hundreds of clients behind one public IP share a single per-IP budget — size for the aggregate, not per client.</p></div><hr><h3 id="thresholds-syn" tabindex="-1"><code>thresholds.syn</code> <a class="header-anchor" href="#thresholds-syn" aria-label="Permalink to &quot;`thresholds.syn`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>YAML path</strong></td><td><code>thresholds.syn</code></td></tr><tr><td><strong>Type</strong></td><td><code>uint64</code></td></tr><tr><td><strong>Default</strong></td><td><code>2000</code> (Hosting/Balanced)</td></tr></tbody></table><p>Maximum TCP SYN packets per second per source IP. This is the primary defense against SYN floods — a single client almost never needs more than a handful of new connections per second.</p><p><strong>When to change it:</strong></p><ul><li><strong>Decrease</strong> (e.g., <code>200</code>–<code>500</code>) for web/API servers where one source opening 2,000 connections/sec is already pathological.</li><li><strong>Increase</strong> for proxy/CDN origins where a single edge node legitimately opens thousands of connections per second.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>SYN cookies at the kernel level complement this rule but don&#39;t stop the packets from consuming NIC interrupts. The XDP drop happens first.</p></div><hr><h3 id="thresholds-udp" tabindex="-1"><code>thresholds.udp</code> <a class="header-anchor" href="#thresholds-udp" aria-label="Permalink to &quot;`thresholds.udp`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>YAML path</strong></td><td><code>thresholds.udp</code></td></tr><tr><td><strong>Type</strong></td><td><code>uint64</code></td></tr><tr><td><strong>Default</strong></td><td><code>10000</code> (Hosting/Balanced)</td></tr></tbody></table><p>Maximum UDP packets per second per source IP. UDP has no handshake, so legitimate per-source rates vary widely by workload (DNS, game servers, VoIP).</p><p><strong>When to change it:</strong></p><ul><li><strong>Decrease</strong> sharply (e.g., <code>500</code>) if you run no UDP services at all.</li><li><strong>Increase</strong> for game servers or media relays where one client can legitimately send tens of thousands of UDP packets per second.</li></ul><hr><h3 id="thresholds-icmp" tabindex="-1"><code>thresholds.icmp</code> <a class="header-anchor" href="#thresholds-icmp" aria-label="Permalink to &quot;`thresholds.icmp`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>YAML path</strong></td><td><code>thresholds.icmp</code></td></tr><tr><td><strong>Type</strong></td><td><code>uint64</code></td></tr><tr><td><strong>Default</strong></td><td><code>500</code> (Hosting/Balanced)</td></tr></tbody></table><p>Maximum ICMP/ICMPv6 packets per second per source IP. Covers ping floods; normal monitoring sends a few pings per second at most.</p><div class="warning custom-block"><p class="custom-block-title">Don&#39;t set this to near-zero</p><p>Path MTU discovery and some health checks depend on ICMP. A floor of ~50–100 per source keeps diagnostics working while still killing floods.</p></div><hr><h3 id="thresholds-new-src" tabindex="-1"><code>thresholds.new_src</code> <a class="header-anchor" href="#thresholds-new-src" aria-label="Permalink to &quot;`thresholds.new_src`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>YAML path</strong></td><td><code>thresholds.new_src</code></td></tr><tr><td><strong>Type</strong></td><td><code>uint64</code></td></tr><tr><td><strong>Default</strong></td><td><code>500</code> (Hosting/Balanced)</td></tr></tbody></table><p><strong>Global</strong> limit of new (previously unseen) source IPs accepted per second. This is the spoofed-source-flood killer: attacks that randomize source addresses can&#39;t exhaust the per-IP tracking map faster than this rate.</p><p><strong>When to change it:</strong></p><ul><li><strong>Decrease</strong> for servers with a stable client base (private APIs, game servers with known player counts).</li><li><strong>Increase</strong> for public websites at launch/marketing spikes, where hundreds of genuinely new visitors per second is normal.</li></ul><div class="info custom-block"><p class="custom-block-title">How it works</p><p>Only packets from sources not already in the <code>ip_stats</code> map count against this limit. Established sources are unaffected, so an ongoing spoofed flood slows the <em>arrival of new clients</em> rather than dropping existing ones.</p></div><hr><h3 id="thresholds-flow-pps" tabindex="-1"><code>thresholds.flow_pps</code> <a class="header-anchor" href="#thresholds-flow-pps" aria-label="Permalink to &quot;`thresholds.flow_pps`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>YAML path</strong></td><td><code>thresholds.flow_pps</code></td></tr><tr><td><strong>Type</strong></td><td><code>uint64</code></td></tr><tr><td><strong>Default</strong></td><td><code>20000</code> (Hosting/Balanced)</td></tr></tbody></table><p>Maximum packets per second per <strong>flow</strong> (source IP + dest IP + protocol + ports). Catches single-connection floods that stay under the per-IP ceiling.</p><p><strong>When to change it:</strong></p><ul><li><strong>Decrease</strong> if individual connections should never be high-rate (HTTP APIs).</li><li><strong>Increase</strong> for bulk-transfer workloads (backups, replication) where one flow legitimately saturates the link.</li></ul><hr><h3 id="thresholds-flow-bps" tabindex="-1"><code>thresholds.flow_bps</code> <a class="header-anchor" href="#thresholds-flow-bps" aria-label="Permalink to &quot;`thresholds.flow_bps`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>YAML path</strong></td><td><code>thresholds.flow_bps</code></td></tr><tr><td><strong>Type</strong></td><td><code>uint64</code> (bytes/sec)</td></tr><tr><td><strong>Default</strong></td><td><code>20000000</code> (~20 MB/s, Hosting/Balanced)</td></tr></tbody></table><p>Maximum bytes per second per flow. The bandwidth twin of <code>flow_pps</code>.</p><div class="warning custom-block"><p class="custom-block-title">Units are bytes, not bits</p><p><code>flow_bps: 20000000</code> is ~20 MB/s ≈ 160 Mbps. A common mistake is entering a megabit value and getting a limit 8× tighter than intended.</p></div><hr><h2 id="_4-auto-ban-ban-duration-sec" tabindex="-1">4. Auto-Ban (<code>ban_duration_sec</code>) <a class="header-anchor" href="#_4-auto-ban-ban-duration-sec" aria-label="Permalink to &quot;4. Auto-Ban (`ban_duration_sec`)&quot;">​</a></h2><h3 id="ban-duration-sec" tabindex="-1"><code>ban_duration_sec</code> <a class="header-anchor" href="#ban-duration-sec" aria-label="Permalink to &quot;`ban_duration_sec`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>YAML path</strong></td><td><code>ban_duration_sec</code></td></tr><tr><td><strong>Type</strong></td><td><code>uint64</code> (seconds)</td></tr><tr><td><strong>Default</strong></td><td><code>300</code> (5 minutes)</td></tr></tbody></table><p>How long a source is auto-banned after exceeding any per-IP threshold. During the ban, <strong>all</strong> packets from that source are dropped — not just the ones over the limit.</p><table tabindex="0"><thead><tr><th>Value</th><th>Behavior</th></tr></thead><tbody><tr><td><code>0</code></td><td>Auto-ban <strong>disabled</strong> — over-limit packets are dropped, but the source can send again the next second</td></tr><tr><td><code>300</code></td><td>5-minute ban (default) — short enough for false positives to recover</td></tr><tr><td><code>3600</code>+</td><td>Aggressive — for repeat-offender environments</td></tr></tbody></table><p><strong>When to change it:</strong></p><ul><li><strong>Increase</strong> if attackers probe until the rate limiter lets them back in.</li><li><strong>Set <code>0</code></strong> if you prefer pure rate limiting without state accumulation (e.g., very legitimate-burst-heavy workloads like game launches).</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Auto-bans live in the per-IP stats map, not the blacklist map. <code>liteshield blacklist list</code> only shows <em>manual</em> bans; the TUI shows the live auto-ban count under <strong>Active bans</strong>.</p></div><hr><h2 id="_5-discord-discord" tabindex="-1">5. Discord (<code>discord</code>) <a class="header-anchor" href="#_5-discord-discord" aria-label="Permalink to &quot;5. Discord (`discord`)&quot;">​</a></h2><p>Outbound webhook alerts. All alerting is in-process — no external notification daemon.</p><h3 id="discord-webhook-url" tabindex="-1"><code>discord.webhook_url</code> <a class="header-anchor" href="#discord-webhook-url" aria-label="Permalink to &quot;`discord.webhook_url`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>YAML path</strong></td><td><code>discord.webhook_url</code></td></tr><tr><td><strong>Type</strong></td><td><code>string</code></td></tr><tr><td><strong>Default</strong></td><td><code>&quot;&quot;</code> (disabled)</td></tr></tbody></table><p>Discord webhook URL (<code>https://discord.com/api/webhooks/...</code>). Empty disables all alerting regardless of the <code>events</code> list.</p><div class="danger custom-block"><p class="custom-block-title">Keep this secret</p><p>Anyone with the webhook URL can post to your channel. The config file is created with mode <code>0600</code> for this reason — don&#39;t widen its permissions, and don&#39;t commit the live file to git.</p></div><hr><h3 id="discord-events" tabindex="-1"><code>discord.events</code> <a class="header-anchor" href="#discord-events" aria-label="Permalink to &quot;`discord.events`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>YAML path</strong></td><td><code>discord.events</code></td></tr><tr><td><strong>Type</strong></td><td><code>[]string</code></td></tr><tr><td><strong>Default</strong></td><td><code>[]</code></td></tr><tr><td><strong>Valid values</strong></td><td><code>rule_trigger</code>, <code>ip_banned</code>, <code>new_source</code></td></tr></tbody></table><p>Which events fire a webhook. Unknown event names fail validation at load time.</p><table tabindex="0"><thead><tr><th>Event</th><th>Fires when</th></tr></thead><tbody><tr><td><code>rule_trigger</code></td><td>Any rate-limit drop counter increases (SYN/UDP/ICMP/PPS)</td></tr><tr><td><code>ip_banned</code></td><td>The active auto-ban count increases</td></tr><tr><td><code>new_source</code></td><td>Packets are dropped by the global new-source limit</td></tr></tbody></table><hr><h3 id="discord-min-interval-sec" tabindex="-1"><code>discord.min_interval_sec</code> <a class="header-anchor" href="#discord-min-interval-sec" aria-label="Permalink to &quot;`discord.min_interval_sec`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td><strong>YAML path</strong></td><td><code>discord.min_interval_sec</code></td></tr><tr><td><strong>Type</strong></td><td><code>int</code> (seconds)</td></tr><tr><td><strong>Default</strong></td><td><code>10</code></td></tr></tbody></table><p>Minimum seconds between two alerts <strong>of the same event type</strong>. Prevents a sustained flood from spamming your channel — during an attack you get one alert per cooldown window instead of one per second.</p><p><strong>When to change it:</strong></p><ul><li><strong>Increase</strong> (e.g., <code>60</code>) if you only need to know an attack started, not that it&#39;s ongoing.</li><li><strong>Decrease</strong> (e.g., <code>5</code>) while actively monitoring an incident.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Values <code>&lt;= 0</code> fall back to the 10-second default at send time — you cannot disable the cooldown.</p></div><hr><h2 id="_6-presets-multipliers" tabindex="-1">6. Presets &amp; Multipliers <a class="header-anchor" href="#_6-presets-multipliers" aria-label="Permalink to &quot;6. Presets &amp; Multipliers&quot;">​</a></h2><p>The installer renders <code>liteshield.yaml</code> from a <strong>preset</strong> (base rates) multiplied by a <strong>traffic profile</strong>. The same numbers live in <code>userspace/internal/config/defaults.go</code> and <code>install.sh</code>.</p><h3 id="base-rates-balanced-1-0×" tabindex="-1">Base rates (Balanced = 1.0×) <a class="header-anchor" href="#base-rates-balanced-1-0×" aria-label="Permalink to &quot;Base rates (Balanced = 1.0×)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Preset</th><th>PPS</th><th>SYN</th><th>UDP</th><th>ICMP</th><th>New src/s</th><th>Flow PPS</th><th>Flow BPS</th></tr></thead><tbody><tr><td><strong>Personal</strong></td><td>50,000</td><td>500</td><td>2,000</td><td>200</td><td>100</td><td>5,000</td><td>5 MB/s</td></tr><tr><td><strong>Hosting</strong></td><td>200,000</td><td>2,000</td><td>10,000</td><td>500</td><td>500</td><td>20,000</td><td>20 MB/s</td></tr><tr><td><strong>Enterprise</strong></td><td>1,000,000</td><td>10,000</td><td>50,000</td><td>2,000</td><td>2,000</td><td>100,000</td><td>100 MB/s</td></tr></tbody></table><h3 id="traffic-profile-multipliers" tabindex="-1">Traffic profile multipliers <a class="header-anchor" href="#traffic-profile-multipliers" aria-label="Permalink to &quot;Traffic profile multipliers&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Profile</th><th>Multiplier</th><th>Use case</th></tr></thead><tbody><tr><td><strong>Strict</strong></td><td>0.5×</td><td>Tight budgets, low-traffic services, maximum paranoia</td></tr><tr><td><strong>Balanced</strong></td><td>1.0×</td><td>Default — sane starting point for most servers</td></tr><tr><td><strong>High</strong></td><td>2.0×</td><td>Burst-heavy legitimate traffic (game servers, launches)</td></tr></tbody></table><h3 id="effective-values-example-personal-×-strict" tabindex="-1">Effective values example (Personal × Strict) <a class="header-anchor" href="#effective-values-example-personal-×-strict" aria-label="Permalink to &quot;Effective values example (Personal × Strict)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Threshold</th><th>Base</th><th>× 0.5</th><th>Effective</th></tr></thead><tbody><tr><td>pps</td><td>50,000</td><td></td><td>25,000</td></tr><tr><td>syn</td><td>500</td><td></td><td>250</td></tr><tr><td>udp</td><td>2,000</td><td></td><td>1,000</td></tr><tr><td>icmp</td><td>200</td><td></td><td>100</td></tr><tr><td>new_src</td><td>100</td><td></td><td>50</td></tr><tr><td>flow_pps</td><td>5,000</td><td></td><td>2,500</td></tr><tr><td>flow_bps</td><td>5,000,000</td><td></td><td>2,500,000</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Start Balanced, tune with data</p><p>Run Balanced for a week, watch <code>liteshield status</code> rule-drop counters during peak hours, then tighten. If legitimate traffic never exceeds 10% of a threshold, that threshold can come down — drops from real users are far more expensive than a slightly permissive limit.</p></div><hr><h2 id="_7-validation-rules" tabindex="-1">7. Validation Rules <a class="header-anchor" href="#_7-validation-rules" aria-label="Permalink to &quot;7. Validation Rules&quot;">​</a></h2><p>The loader rejects these before attach:</p><table tabindex="0"><thead><tr><th>Rule</th><th>Error</th></tr></thead><tbody><tr><td><code>interface</code> empty</td><td><code>interface must not be empty</code></td></tr><tr><td><code>xdp_mode</code> not auto/native/generic</td><td><code>xdp_mode must be auto, native or generic</code></td></tr><tr><td><code>thresholds.pps</code> = 0</td><td><code>thresholds.pps must be &gt; 0</code></td></tr><tr><td>Unknown Discord event</td><td><code>unknown discord event &quot;...&quot;</code></td></tr></tbody></table><p>All other thresholds accept <code>0</code> (effectively disabling that rule&#39;s drops, except where the rule has no zero-check — <code>syn</code>/<code>udp</code>/<code>icmp</code> at <code>0</code> drop all matching packets, since any count exceeds zero).</p><div class="warning custom-block"><p class="custom-block-title">Zero thresholds</p><p>Only <code>flow_pps</code> and <code>flow_bps</code> treat <code>0</code> as &quot;disabled&quot;. Setting <code>syn: 0</code>, <code>udp: 0</code>, or <code>icmp: 0</code> drops <strong>every</strong> packet of that protocol. Leave them at their preset values unless you mean it.</p></div>',117)])])}const g=e(d,[["render",r]]);export{u as __pageData,g as default};
